insert into chunks (document_id, chunk_index, heading, content) values
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 0, 'CÍL', '1 Splnění cíle 2 3 4'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 1, 'ROZSAH PŮSOBNOSTI', '5 a) leasingových smluv, které spadají do působnosti IFRS 16 Leasingy; b) smluv, které spadají do rozsahu působnosti IFRS 17 Pojistné smlouvy. Účetní jednotka se však může rozhodnout použít tento standard na pojistné smlouvy, jejichž primárním účelem je poskytování služeb za pevný poplatek v souladu s odstavcem 8 standardu IFRS 17; c) finančních nástrojů a jiných smluvních práv nebo závazků, které spadají do rozsahu působnosti IFRS 9 Finanční nástroje, IFRS 10 Konsolidovaná účetní závěrka, IFRS 11 Společná ujednání, IAS 27 Samostatná účetní závěrka a IAS 28 Investice do přidružených podniků a společných podniků, a d) nepeněžních směn mezi účetními jednotkami ve stejné oblasti podnikání s cílem usnadnit prodej zákazníkům nebo potenciálním zákazníkům. Tento standard by se například nevztahoval na smlouvy uzavřené mezi dvěma ropnými společnostmi, které se dohodly na směně ropy s cílem včasného uspokojení poptávky svých zákazníků na různých místech určení. 6 7 a) Pokud tyto jiné standardy specifikují, jak oddělit a/nebo prvotně ocenit jednu nebo více částí této smlouvy, účetní jednotka uplatní nejprve požadavky na oddělení a/nebo ocenění uvedené v těchto standardech. Účetní jednotka musí z transakční ceny vyloučit částku týkající se té části (nebo částí) smlouvy, které jsou prvotně oceněny v souladu s jinými standardy, a musí uplatnit odstavce 73–86 pro alokaci částky transakční ceny, která (případně) zbývá, na jednotlivé závazky k plnění spadající do rozsahu působnosti tohoto standardu a na jakékoli další části smlouvy uvedené v odst. 7 písm. b);'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 2, 'ROZSAH PŮSOBNOSTI', 'b) Pokud tyto jiné standardy nespecifikují, jak oddělit a/nebo prvotně ocenit jednu nebo více částí této smlouvy, pak účetní jednotka použije pro oddělení a/nebo prvotní ocenění části (nebo částí) této smlouvy tento standard. 8'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 3, 'UZNÁVÁNÍ', 'Identifikace smlouvy 9 a) smluvní strany smlouvu schválily (písemně, ústně nebo v souladu s jinou běžnou obchodní praxí) a jsou zavázány k plnění svých příslušných závazků; b) účetní jednotka je schopna identifikovat práva jednotlivých stran týkající se zboží nebo služeb, které mají být převedeny; c) účetní jednotka je schopna identifikovat platební podmínky u zboží nebo služeb, které mají být převedeny; d) smlouva má obchodní podstatu (tj. očekává se, že na základě této smlouvy se změní riziko, čas nebo částka budoucích peněžních toků účetní jednotky) a e) je pravděpodobné, že účetní jednotka bude inkasovat protihodnotu, na kterou jí vznikne nárok výměnou za zboží nebo služby, které budou převedeny na zákazníka. Při hodnocení pravděpodobnosti toho, zda je částka protihodnoty inkasovatelná, musí účetní jednotka zvažovat pouze schopnost a úmysl zákazníka tuto částku protihodnoty zaplatit, jakmile nastane její splatnost. Částka protihodnoty, na kterou bude mít účetní jednotka nárok, může být nižší než cena uvedená ve smlouvě, pokud je protihodnota proměnlivá, protože účetní jednotka může zákazníkovi nabídnout cenovou úlevu (viz odstavec 52). 10 11 12 a) účetní jednotka dosud nepřevedla žádné přislíbené zboží ani služby na zákazníka a b) účetní jednotka dosud neobdržela žádnou protihodnotu výměnou za přislíbené zboží nebo služby, ani jí na ni dosud nevznikl nárok. 13 14 15 a) účetní jednotka nemá žádné zbývající závazky spočívající v převedení zboží nebo služeb na zákazníka, a obdržela celou nebo v podstatě celou protihodnotu přislíbenou zákazníkem, která je nevratná, nebo'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 4, 'UZNÁVÁNÍ', 'b) smlouva byla ukončena a protihodnota obdržená od zákazníka je nevratná. 16 Kombinace smluv 17 a) smlouvy jsou sjednány jako balíček s jediným obchodním cílem; b) částka protihodnoty, která má být vyplacena v rámci jedné smlouvy, je závislá na ceně nebo plnění druhé smlouvy, nebo c) zboží nebo služby přislíbené v těchto smlouvách (případně některé zboží nebo služby přislíbené v jednotlivých těchto smlouvách) představují jediný závazek k plnění v souladu s odstavci 22–30. Modifikace smluv 18 19 20 a) zvýší se rozsah působnosti smlouvy vzhledem k přidání přislíbeného zboží nebo služeb, které jsou odlišitelné (v souladu s odstavci 26–30), a b) zvýší se cena smlouvy o částku protihodnoty, která odráží samostatné prodejní ceny účetní jednotky týkající se dalšího přislíbeného zboží nebo služeb a veškeré příslušné úpravy této ceny, jejichž cílem je odrážet okolnosti konkrétní smlouvy. Účetní jednotka může například upravit samostatnou prodejní cenu dalšího zboží nebo služby o slevu, kterou zákazník obdrží, protože není nutné, aby vynaložila náklady související s prodejem, které by vynaložila při prodeji podobného zboží nebo služeb novému zákazníkovi.'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 5, 'UZNÁVÁNÍ', '21 a) účetní jednotka musí zaúčtovat modifikaci smlouvy, jako by se jednalo o ukončení stávající smlouvy a uzavření smlouvy nové, pokud jsou zbývající zboží nebo služby odlišitelné od zboží nebo služeb převedených k datu modifikace smlouvy nebo před tímto datem. Částka protihodnoty, která má být alokována na zbývající závazky k plnění (nebo na zbývající odlišitelné zboží nebo služby v rámci téhož závazku k plnění identifikovaného v souladu s odst. 22 písm. b)) je součtem: i) protihodnoty přislíbené zákazníkem (včetně částek již přijatých od zákazníka), která byla zahrnuta do odhadu transakční ceny a která nebyla uznána jako výnos, a ii) protihodnoty přislíbené v rámci modifikace smlouvy; b) účetní jednotka musí zaúčtovat modifikaci smlouvy, jako by se jednalo o součást stávající smlouvy, pokud zbývající zboží nebo služby nejsou odlišitelné a tvoří tedy součást jediného závazku k plnění, který je k datu modifikace smlouvy částečně splněn. Dopad, který má modifikace smlouvy na transakční cenu a na ukazatel pokroku účetní jednotky směrem k úplnému splnění závazku k plnění, se uznává jako úprava výnosů (buď jako zvýšení nebo jako snížení výnosů) k datu modifikace smlouvy (tj. úprava výnosů se provádí na bázi kumulativního dorovnání); c) pokud zbývající zboží nebo služby představují kombinaci položek a) a b), pak musí účetní jednotka vykázat dopady modifikace na nesplněné (včetně částečně nesplněných) závazky k plnění v modifikované smlouvě způsobem, který je v souladu s cíli tohoto odstavce. Identifikace závazků k plnění'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 6, 'UZNÁVÁNÍ', '22 a) zboží nebo služby (nebo souboru zboží nebo služeb), které jsou odlišitelné, nebo b) série odlišitelného zboží nebo služeb, které jsou v podstatě stejné a které mají stejný způsob převodu na zákazníka (viz odstavec 23). 23 a) každé odlišitelné zboží nebo služba v dané sérii, které účetní jednotka přislíbí převést na zákazníka, by splňovaly kritéria uvedená v odstavci 35 pro závazek k plnění plněný průběžně a b) v souladu s odstavci 39–40 by byla při převodu jakéhokoli odlišitelného zboží nebo služby z dané série na zákazníka použita stejná metoda měření pokroku účetní jednotky směrem k úplnému splnění závazku k plnění. Přísliby ve smlouvách se zákazníky 24 25 Odlišitelné zboží nebo služby 26 a) prodej zboží vytvořeného účetní jednotkou (například zásoby výrobce); b) další prodej zboží zakoupeného účetní jednotkou (například zboží maloobchodního prodejce); c) další prodej práv ke zboží nebo službám zakoupeným účetní jednotkou (například lístek prodaný dále účetní jednotkou jednající v roli odpovědného subjektu, jak je uvedeno v odstavcích B34–B38); d) provedení smluvně dohodnutého úkolu (nebo úkolů) pro zákazníka; e) poskytování služby spočívající v připravenosti poskytnout zboží nebo služby (například nespecifikované aktualizace softwaru, které se poskytují v okamžiku, kdy jsou k dispozici), nebo ve zpřístupnění zboží nebo služeb zákazníkovi k využití tehdy a takovým způsobem, jak zákazník rozhodne;'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 7, 'UZNÁVÁNÍ', 'f) poskytování služby spočívající v zajištění převodu zboží nebo služeb na zákazníka od jiné strany (například jednání v roli zástupce jiné strany, jak je to popsáno v odstavcích B34–B38); g) poskytování práv ke zboží nebo službám, které budou poskytnuty v budoucnosti a které zákazník může dále prodat nebo poskytnout svému zákazníkovi (například účetní jednotka, která prodává výrobek maloobchodnímu prodejci, přislíbí převod dalšího zboží nebo služby na osobu, která tento výrobek od maloobchodního prodejce koupí); h) výstavba, výroba nebo vývoj aktiva z pověření zákazníka; i) poskytování licencí (viz odstavce B52–B63B) a j) poskytování opcí na nákup dalšího zboží nebo služeb (pokud tyto opce poskytují zákazníkovi hmotné právo, jak je popsáno v odstavcích B39–B43). 27 a) zákazník může mít z daného zboží nebo služby prospěch buď samostatně, nebo společně s dalšími zdroji, které jsou zákazníkovi pohotově dostupné (tj. zboží nebo služba jsou schopny být odlišitelné), a b) příslib účetní jednotky převést zboží nebo službu na zákazníka je samostatně identifikovatelný oproti jiným příslibům ve smlouvě (tj. příslib převést zboží nebo službu je odlišitelný v kontextu dané smlouvy).'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 8, 'UZNÁVÁNÍ', '28 29 a) účetní jednotka poskytuje podstatnou službu spočívající v integraci zboží nebo služeb s jiným zbožím nebo službami přislíbenými ve smlouvě do souboru zboží nebo služeb, které představují kombinovaný výstup nebo výstupy, na něž zákazník uzavřel smlouvu. Jinak řečeno, účetní jednotka používá dané zboží nebo služby jako vstupy pro výrobu nebo dodávku kombinovaného výstupu nebo výstupů specifikovaných zákazníkem. Společný výstup nebo výstupy mohou obsahovat více než jednu fázi, prvek nebo jednotku; b) jedna nebo více položek zboží nebo služeb podstatným způsobem modifikuje nebo přizpůsobuje jednu nebo více položek jiného zboží nebo služeb přislíbených ve smlouvě nebo je takovou jednou nebo více položkami modifikována nebo přizpůsobena; c) zboží nebo služby jsou navzájem vysoce závislé nebo do značné míry vzájemně spojené. Jinak řečeno, každá z položek zboží nebo služeb je podstatně ovlivněna jednou nebo více položkami jiného zboží nebo služeb ve smlouvě. V některých případech dvě nebo více položek zboží nebo služeb jsou navzájem podstatně ovlivněny, neboť účetní jednotka by nebyla s to splnit svůj příslib převedením každé z položek daného zboží nebo služeb samostatně. 30 Splnění závazků k plnění 31 32 33 a) využitím aktiva k výrobě zboží nebo poskytování služeb (včetně veřejných služeb); b) využitím aktiva ke zvýšení hodnoty jiných aktiv; c) využitím aktiva k vypořádání závazků nebo ke snížení nákladů; d) prodejem nebo směnou aktiva; e) zastavením aktiva za účelem zajištění úvěru a f) držením aktiva. 34 Závazky k plnění plněné průběžně'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 9, 'UZNÁVÁNÍ', '35 a) zákazník přijímá a spotřebovává požitky plynoucí z plnění poskytovaného účetní jednotkou současně s tím, jak účetní jednotka plnění poskytuje (viz odstavce B3–B4); b) plněním poskytovaným účetní jednotkou vzniká, respektive se zhodnocuje aktivum (například nedokončená výroba), přičemž zákazník toto aktivum kontroluje již v době jeho vytváření nebo zhodnocování (viz odstavec B5), nebo c) plněním poskytovaným účetní jednotkou nevzniká aktivum, pro něž by účetní jednotka měla alternativní využití (viz odstavec 36), a účetní jednotka má právně vymahatelný nárok na úhradu za dosud poskytnuté plnění (viz odstavec 37). 36 37 Závazky k plnění splněné jednorázově 38 a) účetní jednotka má momentální nárok na úhradu daného aktiva – pokud je zákazník aktuálně povinen provést úhradu za dané aktivum, může to nasvědčovat tomu, že tento zákazník získal schopnost řídit využívání aktiva, které je předmětem této výměny, a získat z něho v podstatě veškerý zbývající prospěch; b) zákazník má k danému aktivu právní titul – právní titul může naznačovat, která smluvní strana má schopnost řídit využívání aktiva, získat v podstatě veškerý zbývající prospěch z tohoto aktiva nebo omezit přístup jiných účetních jednotek k tomuto prospěchu. Proto může převod právního titulu k danému aktivu nasvědčovat tomu, že tento zákazník získal kontrolu nad daným aktivem. Pokud si účetní jednotka podrží právní titul pouze jako ochranu proti tomu, že zákazník nezaplatí, nebránila by tato práva účetní jednotky zákazníkovi v tom, aby získal kontrolu nad aktivem;'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 10, 'UZNÁVÁNÍ', 'c) účetní jednotka převedla fyzické vlastnictví daného aktiva – fyzické vlastnictví daného aktiva zákazníkem může nasvědčovat tomu, že zákazník má schopnost řídit využívání tohoto aktiva, získat v podstatě veškerý zbývající prospěch z tohoto aktiva nebo omezit přístup jiných účetních jednotek k tomuto prospěchu. Fyzické vlastnictví však nemusí odpovídat kontrole nad aktivem. Například u některých dohod o zpětném odkupu a u některých konsignačních ujednání může být zákazník nebo příjemce fyzickým vlastníkem aktiva, které kontroluje účetní jednotka. Naopak u některých ujednání o fakturaci před dodáním (tzv. bill-and-hold) může být účetní jednotka fyzickým vlastníkem aktiva, které kontroluje zákazník. Odstavce B64–B76, B77–B78 a B79–B82 poskytují návod na vykazování dohod o zpětném odkupu, konsignačních ujednání a ujednání typu bill-and-hold; d) podstatná rizika a užitky spojené s vlastnictvím aktiva nese zákazník – převod podstatných rizik a užitků spojených s vlastnictvím aktiva na zákazníka může nasvědčovat tomu, že zákazník získal schopnost řídit využívání tohoto aktiva a získat v podstatě veškerý zbývající prospěch z tohoto aktiva. Při vyhodnocování rizik a užitků spojených s vlastnictvím přislíbeného aktiva však musí účetní jednotka vyloučit veškerá rizika, na jejichž základě vzniká samostatný závazek k plnění navíc k závazku k plnění spojenému s převodem aktiva. Účetní jednotka například již převedla kontrolu nad aktivem na zákazníka, avšak dosud nesplnila další závazek k plnění spočívající v poskytování údržbářských služeb v souvislosti s převáděným aktivem;'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 11, 'UZNÁVÁNÍ', 'e) zákazník aktivum přijal – přijetí aktiva zákazníkem může nasvědčovat tomu, že zákazník získal schopnost řídit využívání tohoto aktiva a získat v podstatě veškerý zbývající prospěch z tohoto aktiva. Aby mohla účetní jednotka zhodnotit dopad ustanovení o smluvním přijetí zákazníkem týkající se doby, kdy dojde k převodu kontroly nad aktivem, musí zvážit návod uvedený v odstavcích B83–B86. Měření pokroku směrem k úplnému splnění závazku k plnění 39 40 Metody měření pokroku 41 42 43 Přiměřené ukazatele pokroku 44 45'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 12, 'OCEŇOVÁNÍ', '46 Určení transakční ceny 47 48 a) variabilní protihodnota (viz odstavce 50–55 a 59); b) omezující odhady variabilní protihodnoty (viz odstavce 56–58); c) existence podstatné složky financování ve smlouvě (viz odstavce 60–65); d) nepeněžní protihodnota (viz odstavce 66–69) a e) protihodnota splatná zákazníkovi (viz odstavce 70–72). 49 Variabilní protihodnota 50 51 52 a) zákazník má reálné očekávání vyplývající z běžné obchodní praxe účetní jednotky, jejích zveřejněných pravidel nebo konkrétních prohlášení, že účetní jednotka bude akceptovat částku úhrady, která je nižší než cena uvedená ve smlouvě. To znamená, že se očekává, že účetní jednotka nabídne cenovou úlevu. V závislosti na jurisdikci, odvětví nebo zákazníkovi může být tato nabídka označována jako srážka, sleva, vratka nebo kredit; b) jiné skutečnosti a okolnosti naznačují, že úmyslem účetní jednotky při uzavírání smlouvy se zákazníkem je nabídnout zákazníkovi cenovou úlevu. 53 a) očekávaná hodnota – očekávanou hodnotou se rozumí součet pravděpodobnostně vážených částek v intervalu možných částek protihodnoty. Očekávaná hodnota může být vhodným odhadem částky variabilní protihodnoty, pokud má účetní jednotka velké množství smluv s podobnými charakteristikami;'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 13, 'OCEŇOVÁNÍ', 'b) nejpravděpodobnější částka – nejpravděpodobnější částka je jediná nejpravděpodobnější částka v intervalu možných částek protihodnoty (tj. jediný nejpravděpodobnější výsledek smlouvy). Nejpravděpodobnější částka může být vhodným odhadem částky protihodnoty, pokud má smlouva pouze dva možné výsledky (účetní jednotka například buď získá, nebo nezíská prémii za plnění). 54 Závazky vztahující se k refundaci 55 Omezující odhady variabilní protihodnoty 56 57 a) částka protihodnoty je vysoce citlivá vůči faktorům, které jsou mimo vliv účetní jednotky. Tyto faktory mohou zahrnovat volatilitu trhu, úsudek nebo jednání třetích stran, povětrnostní podmínky a vysoké riziko zastarávání přislíbeného zboží nebo služby; b) předpokládá se, že nejistota týkající se částky protihodnoty zůstane po dlouhou dobu nevyřešena; c) zkušenosti účetní jednotky (nebo jiné důkazy) s podobnými typy smluv jsou omezené nebo mají omezenou prediktivní hodnotu; d) účetní jednotka běžně buď poskytuje širokou škálu cenových úlev, nebo mění platební podmínky u podobných smluv za podobných okolností; e) u dané smlouvy existuje velké množství a široká škála možných částek protihodnoty. 58 Přehodnocení variabilní protihodnoty 59 Existence podstatné složky financování ve smlouvě 60 61 a) případný rozdíl mezi částkou přislíbené protihodnoty a prodejní cenou přislíbeného zboží nebo služeb při hotové úhradě a b) kombinovaný dopad obou následujících faktorů:'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 14, 'OCEŇOVÁNÍ', 'i) očekávané délky období mezi okamžikem, kdy účetní jednotka převede přislíbené zboží nebo služby na zákazníka, a okamžikem, kdy zákazník toto zboží nebo služby uhradí, a ii) převládající úrokové míry na relevantním trhu. 62 a) zákazník zaplatil za zboží nebo služby předem a čas převodu tohoto zboží nebo služeb závisí na rozhodnutí zákazníka; b) podstatná částka protihodnoty přislíbené zákazníkem je variabilní a částka nebo čas této protihodnoty se mění na základě toho, zda dojde nebo nedojde k budoucí události, která v podstatě není pod kontrolou zákazníka nebo účetní jednotky (pokud je například protihodnota licenčním poplatkem založeným na prodeji); c) rozdíl mezi přislíbenou protihodnotou a prodejní cenou zboží nebo služeb hotově hrazených (jak je uvedeno v odstavci 61) vzniká z jiných důvodů, než je poskytování finančních prostředků buď zákazníkovi, nebo účetní jednotce, a rozdíl mezi těmito částkami je úměrný důvodu tohoto rozdílu. Například platební podmínky by mohly účetní jednotce nebo zákazníkovi zajistit ochranu v případě, že by druhá smluvní strana náležitým způsobem nesplnila některé nebo všechny své závazky vyplývající z této smlouvy. 63 64 65 Nepeněžní protihodnota 66 67 68 69 Protihodnota hrazená zákazníkovi 70 71 72 a) účetní jednotka uzná výnosy z převodu daného zboží nebo služby na zákazníka, a b) účetní jednotka uhradí nebo přislíbí uhradit protihodnotu (i v případě, že je tato úhrada podmíněna budoucí událostí). Tento příslib může být implicitní na základě běžné obchodní praxe účetní jednotky. Alokace transakční ceny na závazky k plnění'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 15, 'OCEŇOVÁNÍ', '73 74 75 Alokace na základě samostatných prodejních cen 76 77 78 79 a) přístup upraveného tržního zhodnocení – účetní jednotka by mohla vyhodnotit trh, na kterém prodává zboží nebo služby, a odhadnout cenu, kterou by byl zákazník na tomto trhu ochoten za toto zboží nebo služby zaplatit. Tento přístup může zahrnovat rovněž odkaz na ceny podobného zboží nebo služeb konkurentů účetní jednotky a úpravu těchto cen podle potřeby tak, aby odrážela náklady a marže účetní jednotky; b) metoda oceňování pořizovacími náklady a přirážkou – účetní jednotka může předpovědět své očekávané náklady na splnění závazku k plnění a přidat k nim přiměřenou marži pro dané zboží nebo službu; c) zbytkový přístup – účetní jednotka může odhadnout samostatnou prodejní cenu odkazem na celkovou transakční cenu sníženou o součet objektivně zjistitelných samostatných prodejních cen jiného zboží nebo služeb přislíbených ve smlouvě. Účetní jednotka však může použít zbytkový přístup k tomu, aby v souladu s odstavcem 78 odhadla samostatnou prodejní cenu zboží nebo služby, pouze tehdy, je-li splněno jedno z následujících kritérií: i) účetní jednotka prodává totéž zboží nebo službu různým zákazníkům (současně nebo téměř současně) za široké spektrum částek (tj. prodejní cena je vysoce variabilní, protože reprezentativní samostatná prodejní cena není rozeznatelná od minulých transakcí nebo jiných objektivně zjistitelných důkazů), nebo ii) účetní jednotka dosud nestanovila cenu za dané zboží nebo službu a toto zboží nebo služba nebyly dříve prodávány na samostatném základě (tj. prodejní cena je nejistá).'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 16, 'OCEŇOVÁNÍ', '80 Alokace slevy 81 82 a) účetní jednotka pravidelně prodává každé odlišitelné zboží nebo službu (nebo každý soubor odlišitelného zboží nebo služeb) ve smlouvě na samostatném základě; b) účetní jednotka rovněž pravidelně prodává na samostatném základě soubor (nebo soubory) některého tohoto odlišitelného zboží nebo služeb se slevou ze samostatných prodejních cen zboží nebo služeb u každého souboru a c) sleva přiřaditelná každému souboru zboží nebo služeb popsaných v odst. 82 písm. b) je v podstatě stejná jako sleva ve smlouvě a z analýzy zboží nebo služeb v každém souboru vyplývá objektivně zjistitelný důkaz závazku k plnění, k němuž celá sleva ve smlouvě náleží. 83 Alokace variabilní protihodnoty 84 a) jeden nebo více, ale ne všechny, závazky k plnění uvedené ve smlouvě (například prémie může být podmíněna tím, že účetní jednotka převede přislíbené zboží nebo službu v určitém časovém období); b) jeden nebo více, ale ne všechny, odlišitelné zboží nebo služby přislíbené v sérii odlišitelného zboží nebo služeb, která je součástí jediného závazku k plnění v souladu s odst. 22 písm. b), (například protihodnota přislíbená za druhý rok dvouleté smlouvy na úklidové služby se zvýší na základě pohybů specifikovaného indexu inflace). 85 a) podmínky variabilní úhrady se vztahují konkrétně k úsilí účetní jednotky splnit závazek k plnění nebo převést odlišitelné zboží nebo službu (nebo se vztahují ke konkrétnímu výstupu vyplývajícímu ze splnění závazku k plnění nebo z převodu odlišitelného zboží nebo služby) a'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 17, 'OCEŇOVÁNÍ', 'b) alokace variabilní částky protihodnoty v plném rozsahu na závazek plnění nebo na odlišitelné zboží nebo služby je v souladu s cílem alokace uvedeným v odstavci 73 při zvážení všech závazků k plnění a platebních podmínek ve smlouvě. 86 Změny transakční ceny 87 88 89 90 a) účetní jednotka musí alokovat změnu transakční ceny na závazky k plnění identifikované ve smlouvě před touto modifikací, pokud je změna transakční ceny přiřaditelná částce variabilní protihodnoty přislíbené před provedením této modifikace a v tom rozsahu, ve kterém je přiřaditelná, a tato modifikace je zaúčtována v souladu s odst. 21 písm. a); b) ve všech ostatních případech, kdy modifikace nebyla zaúčtována jako samostatná smlouva v souladu s odstavcem 20, musí účetní jednotka alokovat změnu transakční ceny na závazky k plnění v modifikované smlouvě (tj. závazky k plnění, které bezprostředně po této modifikaci nebyly splněny nebo byly splněny jen částečně).'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 18, 'NÁKLADY SMLOUVY', 'Přírůstkové náklady na získání smlouvy 91 92 93 94 Náklady související s plněním smlouvy 95 a) náklady přímo souvisejí se smlouvou nebo s očekávanou smlouvou, kterou účetní jednotka může konkrétně identifikovat (například náklady související se službami, které mají být poskytnuty na základě obnovení stávající smlouvy, nebo náklady na návrh aktiva, které má být převedeno podle konkrétní smlouvy, která dosud nebyla schválena); b) náklady vytvářejí nebo zvyšují zdroje účetní jednotky, které budou použity k plnění (nebo pokračování v plnění) závazků k plnění v budoucnosti, a c) předpokládá se, že náklady budou zpětně získány. 96 97 a) přímé osobní náklady (například platy a mzdy zaměstnanců, kteří poskytují přislíbené služby přímo zákazníkovi); b) přímý materiál (například zásoby použité při poskytování přislíbené služby zákazníkovi); c) alokace nákladů, které souvisejí přímo se smlouvou nebo se smluvními činnostmi (například náklady na řízení zakázky nebo na dohled nad ní, pojištění a odpisy nástrojů, zařízení a aktiv z práv k užíváním, které se užívají při plnění smlouvy); d) náklady, které jsou výslovně vyúčtovány zákazníkovi podle smlouvy, a e) jiné náklady, které jsou vynaloženy pouze z toho důvodu, že účetní jednotka uzavřela danou smlouvu (například platby subdodavatelům). 98 a) správní a režijní náklady (pokud nejsou tyto náklady výslovně vyúčtovány zákazníkovi podle smlouvy; v takovém případě musí účetní jednotka tyto náklady ocenit v souladu s odstavcem 97);'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 19, 'NÁKLADY SMLOUVY', 'b) náklady na odpadový materiál, práci nebo jiné zdroje pro plnění smlouvy, které nebyly zohledněny v ceně smlouvy; c) náklady vztahující se ke splněným závazkům k plnění (nebo k částečně splněným závazkům k plnění) uvedeným ve smlouvě (tj. náklady, které se vztahují k minulému plnění) a d) náklady, u nichž účetní jednotka nemůže rozlišit, zda se vztahují k nesplněným závazkům k plnění nebo ke splněným závazkům k plnění (případně k částečně splněným závazkům k plnění). Odpisy nehmotných aktiv a znehodnocení 99 100 101 a) zbývající částku protihodnoty, jejíž obdržení účetní jednotka očekává výměnou za zboží nebo služby, ke kterým se toto aktivum vztahuje, sníženou o b) náklady, které se vztahují přímo k poskytování tohoto zboží nebo služeb a které nebyly uznány jako náklady (viz odstavec 97). 102 103 104'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 20, 'VYKÁZÁNÍ', '105 106 107 108 109'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 21, 'ZVEŘEJNĚNÍ', '110 a) své smlouvy uzavřené se zákazníky (viz odstavce 113–122); b) podstatné úsudky a změny těchto úsudků provedené při uplatňování tohoto standardu na tyto smlouvy (viz odstavce 123–126) a c) veškerá aktiva uznaná na základě nákladů na získání nebo splnění smlouvy se zákazníkem v souladu s odstavcem 91 nebo 95 (viz odstavce 127–128). 111 112 Smlouvy se zákazníky 113 a) uznané výnosy ze smluv se zákazníky, které účetní jednotka musí zveřejnit odděleně od svých ostatních zdrojů výnosů, a b) veškeré ztráty ze znehodnocení uznané (v souladu s IFRS 9) u veškerých pohledávek nebo smluvních aktiv vzniklých na základě smluv účetní jednotky se zákazníky, které účetní jednotka musí zveřejnit odděleně od ztrát ze znehodnocení z jiných smluv. Členění výnosů 114 115 Smluvní zůstatky 116 a) počáteční a konečné zůstatky pohledávek, smluvních aktiv a smluvních závazků ze smluv se zákazníky, pokud nejsou jinak samostatně prezentovány nebo zveřejněny; b) výnosy uznané ve vykazovaném období, které byly zahrnuty do zůstatku smluvního závazku na počátku tohoto období, a c) výnosy uznané ve vykazovaném období plynoucí ze závazků k plnění splněných (nebo částečně splněných) v předchozích obdobích (například změny transakční ceny). 117 118 a) změny v důsledku podnikových kombinací;'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 22, 'ZVEŘEJNĚNÍ', 'b) úpravy výnosů na bázi kumulativního dorovnání, které ovlivňují příslušné smluvní aktivum nebo smluvní závazek, včetně úprav vznikajících na základě změny ukazatele pokroku, změny odhadu transakční ceny (včetně veškerých změn při posuzování toho, zda je odhad variabilní protihodnoty omezen), nebo modifikace smlouvy; c) znehodnocení smluvního aktiva; d) změnu časového rámce, v němž se právo na protihodnotu stalo nepodmíněným (tj. k reklasifikaci smluvního aktiva na pohledávku), a e) změna časového rámce pro splnění závazku k plnění (tj. pro uznání výnosů vzniklých na základě smluvního závazku). Závazky k plnění 119 a) kdy účetní jednotka obvykle splní své závazky k plnění (například při dodávce, při doručení, při poskytování služeb nebo při dokončení služby), včetně situace, kdy jsou závazky k plnění splněny v rámci ujednání typu bill-and-hold; b) podstatných platebních podmínek (například obvyklé doby splatnosti úhrady, zda smlouva obsahuje podstatnou složku financování, zda je částka protihodnoty variabilní a zda je odhad variabilní protihodnoty obvykle omezen v souladu s odstavci 56–58); c) povahy zboží nebo služeb, jejichž převod účetní jednotka přislíbila, se zdůrazněním veškerých závazků k plnění umožňujících zajištění převodu zboží nebo služby pro jinou smluvní stranu (tj. pokud účetní jednotka působí jako zástupce); d) závazků týkajících se vratek, refundací a jiných podobných závazků a e) typů záruk a souvisejících povinností. Transakční cena alokovaná na zbývající závazky k plnění'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 23, 'ZVEŘEJNĚNÍ', '120 a) souhrnnou částku transakční ceny alokovanou na závazky k plnění, které jsou nesplněny (případně částečně nesplněny) ke konci vykazovaného období, a b) vysvětlení, kdy účetní jednotka očekává, že uzná do výnosů částku zveřejněnou v souladu s odst. 120 písm. a), kterou musí zveřejnit kterýmkoli z následujících způsobů: i) na kvantitativním základě s využitím časových pásem, která by byla nejvhodnější pro dobu trvání zbývajících závazků k plnění; ii) s využitím kvalitativních informací. 121 a) závazek k plnění je součástí smlouvy, jejíž původně očekávaná doba trvání činila jeden rok nebo méně, nebo b) účetní jednotka uznává výnosy ze splnění závazku k plnění v souladu s odstavcem B16. 122 Podstatné úsudky použité při aplikaci tohoto standardu 123 a) čas splnění závazků k plnění (viz odstavce 124–125) a b) transakční cena a částky alokované na závazky k plnění (viz odstavec 126). Určení času splnění závazků k plnění 124 a) metody užité při uznávání výnosů (například popis použitých metod výstupů nebo vstupů a způsob, jakým jsou tyto metody uplatňovány), a b) vysvětlení, proč použité metody poskytují důvěryhodné zobrazení převodu zboží nebo služeb. 125 Určení transakční ceny a částek alokovaných na závazky k plnění 126 a) určení transakční ceny, které zahrnuje mimo jiné odhad variabilní protihodnoty, úpravu této protihodnoty o dopady časové hodnoty peněz a ocenění nepeněžní protihodnoty; b) posouzení toho, zda je odhad variabilní protihodnoty omezen;'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 24, 'ZVEŘEJNĚNÍ', 'c) alokace transakční ceny, včetně odhadu samostatných prodejních cen přislíbeného zboží nebo služeb, a alokace slev a variabilní protihodnoty na konkrétní část smlouvy (pokud je to relevantní) a d) oceňování závazků týkajících se vratek, refundací a jiných podobných závazků. Aktiva uznávaná na základě nákladů na získání nebo splnění smlouvy se zákazníkem 127 a) úsudky provedené při určování částky nákladů vynaložených na získání nebo splnění smlouvy se zákazníkem (v souladu s odstavcem 91 nebo 95) a b) metodu, kterou používá k určení odpisů pro každé vykazované období. 128 a) konečné zůstatky aktiv uznaných na základě nákladů vynaložených na získání nebo splnění smlouvy se zákazníkem (v souladu s odstavcem 91 nebo 95) podle hlavních kategorií aktiv (například náklady na získání smluv se zákazníky, náklady vynaložené před uzavřením smlouvy a náklady na vypracování smlouvy) a b) částku odpisů a veškeré ztráty ze znehodnocení uznané ve vykazovaném období. Praktická zjednodušení 129 Dodatek A Definice pojmů Tento dodatek je nedílnou součástí standardu. smlouva Dohoda mezi dvěma nebo více smluvními stranami, v jejímž důsledku vznikají vymahatelná práva a závazky. smluvní aktivum Právo účetní jednotky na protihodnotu výměnou za zboží nebo služby, které účetní jednotka převedla na zákazníka v případě, že je toto právo podmíněno něčím jiným, než je plynutí času (například budoucím plněním účetní jednotky). smluvní závazek'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 25, 'ZVEŘEJNĚNÍ', 'Závazek účetní jednotky převést zboží nebo služby na zákazníka, za který účetní jednotka obdržela od zákazníka protihodnotu (případně jí na tuto částku vznikl nárok). zákazník Strana, která uzavřela s účetní jednotkou smlouvu za účelem získání zboží nebo služeb, které jsou výstupem běžné činnosti účetní jednotky, výměnou za protihodnotu. příjem Zvýšení ekonomických užitků v průběhu účetního období formou nabytí aktiv či zvýšení jejich hodnoty, anebo snížení závazků, jehož důsledkem je takové zvýšení vlastního kapitálu, které nesouvisí s jeho zvýšením na základě příspěvků vlastníků. závazek k plnění Příslib ve smlouvě se zákazníkem převést na zákazníka buď: a) zboží nebo služby (nebo soubor zboží nebo služeb), které jsou odlišitelné, nebo b) série odlišitelného zboží nebo služeb, které jsou v podstatě stejné a které má stejný způsob převodu na zákazníka. výnosy Příjem vznikající z běžných činností účetní jednotky. samostatná prodejní cena (zboží nebo služby) Samostatná prodejní cena je cena, za kterou by účetní jednotka prodala přislíbené zboží nebo službu zákazníkovi samostatně. transakční cena (u smlouvy se zákazníkem) Částka protihodnoty, na kterou má účetní jednotka dle svého názoru nárok výměnou za převod přislíbeného zboží nebo služeb na zákazníka, s výjimkou částek přijatých jménem třetích stran. Dodatek B Aplikační příručka Tento dodatek je nedílnou součástí standardu. Popisuje použití odstavců 1–129 a má stejnou závaznost jako ostatní části tohoto standardu.'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 26, 'B1', 'a) závazky k plnění plněné průběžně (odstavce B2–B13); b) metody měření pokroku směrem k úplnému splnění závazku k plnění (odstavce B14–B19); c) prodej s právem na vrácení (odstavce B20–B27); d) záruky (odstavce B28–B33); e) přístupy v případě odpovědného subjektu a zástupce (odstavce B34–B38); f) opce zákazníka na další zboží nebo služby (odstavce B39–B43); g) neuplatněná práva zákazníků (odstavce B44–B47); h) nevratné poplatky hrazené předem (a některé související náklady) (odstavce B48–B51); i) poskytování licence (odstavce B52–B63B); j) dohody o zpětném odkupu (odstavce B64–B76); k) konsignační ujednání (odstavce B77–B78); l) ujednání typu bill-and-hold (odstavce B79–B82); m) přijetí zákazníkem (odstavce B83–B86) a n) zveřejňování rozčleněných výnosů (odstavce B87–B89). Závazky k plnění plněné průběžně'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 27, 'B2', 'a) zákazník přijímá a spotřebovává požitky plynoucí z plnění poskytovaného účetní jednotkou současně s tím, jak účetní jednotka plnění poskytuje (viz odstavce B3–B4); b) plněním poskytovaným účetní jednotkou vzniká, respektive se zhodnocuje aktivum (například nedokončená výroba), přičemž zákazník toto aktivum kontroluje již v době jeho vytváření nebo zhodnocování (viz odstavec B5), nebo c) plněním poskytovaným účetní jednotkou nevzniká aktivum, pro něž by účetní jednotka měla alternativní využití (viz odstavce B6–B8), a účetní jednotka má právně vymahatelný nárok na úhradu za dosud poskytnuté plnění (viz odstavce B9–B13). Současné přijímání a spotřeba požitků plynoucích z plnění účetní jednotky (odst. 35 písm. a))'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 28, 'B4', 'a) nebrat v úvahu potenciální smluvní nebo praktická omezení, která by účetní jednotce jinak zabránila v převodu zbývajícího závazku k plnění na jinou účetní jednotku, a b) předpokládat, že jiná účetní jednotka, která by plnila zbývající závazek k plnění, by neměla požitek z žádného aktiva, které je v současné době účetní jednotkou kontrolováno a které by bylo účetní jednotkou kontrolováno i nadále, pokud by byl závazek k plnění převeden na jinou účetní jednotku. Zákazník kontroluje aktivum již v době jeho vytváření nebo zhodnocování (odst. 35 písm. b))'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 29, 'B5', 'Plněním poskytovaným účetní jednotkou nevzniká aktivum, pro něž by účetní jednotka měla alternativní využití (odst. 35 písm. c))'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 30, 'B8', 'Právo na úhradu za dosud poskytnuté plnění (odst. 35 písm. c))'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 31, 'B9', 'a) podíl očekávané ziskové marže ve smlouvě, který přiměřeně odráží rozsah plnění smlouvy účetní jednotkou před jejím ukončením ze strany zákazníka (nebo jinou smluvní stranou), nebo b) přiměřenou návratnost nákladů kapitálu účetní jednotky u podobných smluv (nebo typická provozní marže účetní jednotky u podobných smluv), pokud je marže u konkrétní smlouvy vyšší než výnos, který účetní jednotka obvykle z podobných smluv získá.'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 32, 'B12', 'a) právní předpisy, správní praxe nebo právní precedens zajišťují účetní jednotce právo na úhradu za dosud provedené plnění, i když toto právo není specifikováno ve smlouvě se zákazníkem; b) příslušný právní precedens naznačuje, že podobná práva na úhradu za dosud provedené plnění v podobných smlouvách nemají právně závazný účinek, nebo c) výsledkem běžné obchodní praxe účetní jednotky spočívající v tom, že se účetní jednotka rozhodla právo na úhradu nevymáhat, je to, že se právo v daném právním prostředí stalo nevymahatelným. Bez ohledu na to, zda se účetní jednotka rozhodla vzdát se svého práva na úhradu u podobných smluv, by však měla i nadále nárok na úhradu k danému dni v případě, že by její právo na úhradu za dosud provedené plnění uvedené ve smlouvě se zákazníkem bylo i nadále vymahatelné.'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 33, 'B13', 'Metody měření pokroku směrem k úplnému splnění závazku k plnění'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 34, 'B14', 'a) metody výstupů (viz odstavce B15–B17) a b) metody vstupů (viz odstavce B18–B19). Metody výstupů'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 35, 'B17', 'Metody vstupů'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 36, 'B19', 'a) když vynaložené náklady nepřispívají k pokroku účetní jednotky směřujícímu ke splnění závazku k plnění. Účetní jednotka by například neuznala výnosy na základě vynaložených nákladů přiřaditelných k podstatným neefektivním výdajům souvisejícím s plněním účetní jednotky, které se neodrazily ve smluvní ceně (například náklady na neočekávané množství odpadového materiálu, práce nebo jiné zdroje, které byly vynaloženy s cílem splnit závazek k plnění); b) když vynaložené náklady nejsou úměrné pokroku účetní jednotky směřujícímu ke splnění závazku k plnění. Za těchto okolností může být nejlepším zobrazením plnění účetní jednotky úprava metody vstupů tak, aby byly výnosy uznávány pouze v rozsahu těchto vynaložených nákladů. Důvěryhodným zobrazením plnění účetní jednotky by mohlo být například uznání výnosů v částce rovnající se nákladům na pořízení zboží užitého ke splnění závazku k plnění, pokud účetní jednotka při uzavření smlouvy očekává, že budou splněny všechny následující podmínky: i) zboží není odlišitelné; ii) předpokládá se, že zákazník získá kontrolu nad zbožím podstatně dříve, než obdrží služby vztahující se k tomuto zboží; iii) náklady vynaložené na převáděné zboží jsou podstatné v poměru k celkovým očekávaným nákladům na úplné splnění závazku k plnění a iv) účetní jednotka získá zboží od třetí strany a podstatně se neangažuje při návrhu a výrobě tohoto zboží (avšak jedná jako odpovědný subjekt v souladu s odstavci B34–B38). Prodej s právem na vrácení'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 37, 'B20', 'a) plnou nebo částečnou refundaci jakékoli uhrazené protihodnoty; b) úvěr, který lze použít proti dlužným částkám nebo který bude dlužný účetní jednotce, a c) jiný produkt výměnou.'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 38, 'B21', 'a) výnosy z převedených produktů v částce protihodnoty, na kterou má účetní jednotka dle vlastního očekávání nárok (výnosy by proto nebyly uznány u produktů, u nichž se předpokládá vrácení); b) závazek vztahující se k refundaci a c) aktivum (a odpovídající úpravu nákladů na prodej) vztahující se k jeho právu zpětně získat produkty od zákazníků při úhradě závazku k refundaci.'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 39, 'B27', 'Záruky'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 40, 'B31', 'a) zda je záruka vyžadována právními předpisy – pokud je účetní jednotka na základě právních předpisů povinna poskytnout záruku, existence těchto právních předpisů svědčí o tom, že přislíbená záruka nepředstavuje závazek k plnění, protože takové požadavky zpravidla existují proto, aby chránily zákazníky před rizikem nákupu vadných produktů; b) délku období, na které se záruka vztahuje – čím delší je toto období, tím větší je pravděpodobnost, že přislíbená záruka představuje závazek k plnění, protože je pravděpodobnější, že poskytuje službu navíc k ujištění, že produkt je v souladu s dohodnutými specifikacemi; c) povahu úkolů, které účetní jednotka přislíbí provést – pokud je nutné, aby účetní jednotka provedla určité úkoly s cílem poskytnout ujištění, že produkt je v souladu s dohodnutými specifikacemi (například služba zpětného zaslání vadného produktu), pak tyto úkoly pravděpodobně nevedou ke vzniku závazku k plnění.'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 41, 'B33', 'Přístupy v případě odpovědného subjektu a zástupce'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 42, 'B34A', 'a) identifikovat stanovené zboží nebo služby, které mají být poskytnuty zákazníkovi (což by například mohlo být právo obdržet zboží nebo službu poskytované jinou stranou (viz odstavec 26)) a b) posoudit, zda má kontrolu (jak je popsáno v odstavci 33) nad každým stanoveným zbožím nebo službou před jejich převodem na zákazníka.'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 43, 'B35A', 'a) zbožím nebo jiným aktivem od této druhé strany, které následně převede na zákazníka; b) právem obdržet službu poskytovanou jinou stranou, což dává účetní jednotce možnost řídit uvedenou stranu tak, aby tuto službu poskytla zákazníkovi jménem účetní jednotky; c) zbožím nebo službou od jiné strany, které poté zkombinuje s jiným zbožím nebo službami a tak poskytne stanovené zboží nebo služby zákazníkovi. Poskytuje-li například účetní jednotka podstatnou službu spočívající v zahrnutí zboží nebo služeb (viz odst. 29 písm. a)) poskytovaných jinou stranou do stanoveného zboží nebo služby, na nějž zákazník uzavřel smlouvu, má účetní jednotka kontrolu nad stanoveným zbožím nebo službou, než jsou převedeny na zákazníka. Důvodem je to, že účetní jednotka nejprve získá kontrolu nad vstupy pro stanovené zboží nebo službu (což zahrnuje zboží nebo služby od jiné strany) a řídí jejich používání s cílem vytvořit kombinovaný výstup, kterým je stanovené zboží nebo služba.'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 44, 'B37', 'a) účetní jednotka je primárně odpovědná za splnění příslibu poskytnout stanovené zboží nebo službu. Toto obvykle zahrnuje odpovědnost za přijatelnost stanoveného zboží nebo služby (například primární odpovědnost za to, že zboží nebo služba odpovídají zákazníkovým specifikacím). Pokud je účetní jednotka primárně odpovědná za splnění příslibu k poskytnutí stanoveného zboží nebo služby, může to znamenat, že jiná strana zapojená do poskytnutí stanoveného zboží nebo služby jedná jménem účetní jednotky; b) účetní jednotka nese riziko znehodnocení zásob před převedením stanoveného zboží nebo služby na zákazníka nebo po převedení kontroly na zákazníka (například pokud má zákazník právo zboží nebo službu vrátit). Pokud například účetní jednotka získá nebo se zaváže získat stanovené zboží nebo službu před získáním smlouvy se zákazníkem, může to naznačovat, že účetní jednotka má schopnost řídit využívání tohoto zboží nebo služby a získat v podstatě veškerý zbývající prospěch z tohoto zboží nebo služby před jejich převodem na zákazníka;'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 45, 'B37', 'c) účetní jednotka má prostor pro cenotvorbu za stanovené zboží nebo službu. Stanovení ceny, kterou zákazník za stanovené nebo službu zaplatí, může naznačovat, že účetní jednotka má schopnost řídit využívání tohoto zboží nebo služby a získat v podstatě veškerý zbývající prospěch. V některých případech však může mít prostor pro cenotvorbu zástupce. Zástupce může mít například určitou flexibilitu při stanovování cen, aby generoval další výnosy ze svých služeb spočívajících v zajištění toho, aby zboží nebo služby byly zákazníkům poskytnuty jinými stranami.'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 46, 'B38', 'Opce zákazníka na další zboží nebo služby'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 47, 'B42', 'a) jakoukoli slevu, kterou by zákazník získal, aniž by uplatnil opci, a b) pravděpodobnost, že opce bude uplatněna.'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 48, 'B43', 'Neuplatněná práva zákazníků'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 49, 'B47', 'Nevratné poplatky hrazené předem (a některé související náklady)'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 50, 'B51', 'Poskytování licencí'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 51, 'B52', 'a) software a technologie; b) filmy, hudbu a další formy médií a zábavy; c) franšízy a d) patenty, ochranné známky a autorská práva.'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 52, 'B54', 'a) licence, která je složkou hmotného zboží a která je nedílnou součástí funkčnosti tohoto zboží, a b) licence, kterou může zákazník využívat pouze ve spojení se související službou (například online služba poskytovaná účetní jednotkou, která prostřednictvím poskytnutí licence umožňuje zákazníkovi přístup k obsahu).'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 53, 'B56', 'a) právo na přístup k duševnímu vlastnictví účetní jednotky tak, jak existuje v průběhu licenčního období, nebo b) právo na využití duševního vlastnictví účetní jednotky tak, jak existuje v okamžiku, kdy je licence poskytnuta. Určení povahy příslibu účetní jednotky'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 54, 'B58', 'a) smlouva vyžaduje nebo zákazník přiměřeně očekává, že účetní jednotka bude provádět činnosti, které podstatně ovlivní duševní vlastnictví, k němuž má zákazník práva (viz odstavce B59 a B59A); b) práva poskytnutá na základě licence zákazníka přímo vystavují případným pozitivním nebo negativním dopadům činnosti účetní jednotky uvedeným v odst. B58 písm. a) a c) výsledkem těchto činností není převod zboží nebo služby na zákazníka v průběhu provádění těchto činností (viz odstavec 25).'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 55, 'B59A', 'a) tyto činnosti mají podle očekávání podstatně změnit formu (například konstrukci nebo obsah) nebo funkčnost (například schopnost provádět nějakou funkci nebo úkol) tohoto duševního vlastnictví nebo b) schopnost zákazníka získat prospěch z duševního vlastnictví, z těchto činností ve značné míře vyplývá, nebo na nich závisí. Například prospěch z obchodní značky často vyplývá z pokračujících činností účetní jednotky, které podporují či udržují hodnotu duševního vlastnictví, nebo na takových činnostech závisí. V souladu s tímto, pokud duševní vlastnictví, k němuž má zákazník práva, má podstatnou samostatnou funkci, podstatná část požitku z tohoto duševního vlastnictví vyplývá z této funkce. V důsledku toho schopnost zákazníka získat prospěch z tohoto duševní vlastnictví by tudíž nebyla podstatně dotčena činnostmi účetní jednotky, ledaže tyto činnosti podstatně změní formu nebo funkci tohoto duševního vlastnictví. Druhy duševního vlastnictví, jež mají často podstatné samostatné funkce, zahrnují software, biologické sloučeniny nebo vzorce léků a dotvořený mediální obsah (například filmy, televizní programy a hudební nahrávky).'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 56, 'B62', 'a) omezení z hlediska času, zeměpisné oblasti nebo využití – tato omezení definují atributy přislíbené licence, nikoli to, zda účetní jednotka splňuje svůj závazek k plnění jednorázově nebo průběžně; b) záruky poskytnuté účetní jednotkou, že má platný patent na duševní vlastnictví a že bude tento patent chránit proti neoprávněnému používání – příslib chránit práva k patentu nepředstavuje závazek k plnění, protože ochrana patentu chrání hodnotu duševního vlastnictví účetní jednotky a poskytuje zákazníkovi ujištění, že převedená licence splňuje specifikace licence přislíbené ve smlouvě. Licenční poplatky založené na prodeji nebo na využívání'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 57, 'B63', 'a) dojde k následnému prodeji nebo využívání a b) dojde ke splnění (nebo k částečnému splnění) závazku k plnění, na nějž byly alokovány některé nebo všechny licenční poplatky založené na prodeji nebo na využívání.'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 58, 'B63B', 'Dohody o zpětném odkupu'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 59, 'B65', 'a) závazek účetní jednotky ke zpětnému odkupu (dohoda o budoucím zpětném odkupu); b) právo účetní jednotky na zpětný odkup (kupní opce) a c) závazek účetní jednotky ke zpětnému odkupu na žádost zákazníka (prodejní opce). Dohoda o budoucím zpětném odkupu nebo kupní opce'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 60, 'B66', 'a) jako leasing v souladu s IFRS 16 Leasingy, pokud účetní jednotka může nebo musí dané aktivum zpětně odkoupit za částku, která je nižší než původní prodejní cena tohoto aktiva s výjimkou případů, kdy je tato smlouva součástí transakce prodeje a zpětného leasingu. Pokud je tato smlouva součástí transakce prodeje a zpětného leasingu, musí účetní jednotka dané aktivum nadále uznávat a musí uznat i finanční závazek z jakékoli protihodnoty přijaté od zákazníka. Účetní jednotka musí takový finanční závazek zaúčtovat v souladu s IFRS 9; nebo b) jako dohodu o financování v souladu s odstavcem B68, pokud účetní jednotka může nebo musí dané aktivum zpětně odkoupit za částku, která je rovna původní prodejní ceně tohoto aktiva nebo je vyšší.'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 61, 'B69', 'Prodejní opce'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 62, 'B76', 'Konsignační ujednání'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 63, 'B78', 'a) produkt je kontrolován účetní jednotkou, dokud nenastane určitá událost, například že prodejce prodá produkt zákazníkovi, nebo dokud nevyprší dané časové období; b) účetní jednotka může vyžadovat vrácení produktu nebo jeho převod třetí straně (například jinému prodejci) a c) prodejce nemá nepodmíněný závazek zaplatit za daný produkt (ačkoli může mít povinnost uhradit zálohu). Ujednání typu bill-and-hold'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 64, 'B81', 'a) musí existovat podstatný důvod pro ujednání typu bill-and-hold (toto ujednání si například vyžádá zákazník); b) produkt musí být samostatně rozlišen s tím, že náleží zákazníkovi; c) produkt musí být aktuálně připraven k fyzickému převodu na zákazníka a d) účetní jednotka nesmí mít možnost produkt využívat nebo ho přesměrovat na jiného zákazníka.'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 65, 'B82', 'Přijetí zákazníkem'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 66, 'B86', 'Zveřejňování rozčleněných výnosů'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 67, 'B88', 'a) zveřejňování prezentovaná mimo účetní závěrku (například ve zveřejnění výsledků, výročních zprávách nebo ve zprávách pro investory); b) informace pravidelně přezkoumávané vedoucí osobou s provozní rozhodovací pravomocí za účelem vyhodnocování finanční výkonnosti provozních segmentů a c) jiné informace, které jsou podobné typům informací uvedených v odst. B88 písm. a) a b) a které účetní jednotka nebo uživatelé účetní závěrky účetní jednotky používají k vyhodnocení finanční výkonnosti účetní jednotky nebo k rozhodování o přidělení zdrojů.'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 68, 'B89', 'a) typ zboží nebo služby (například významné druhy produktů); b) zeměpisná oblast (například země nebo region); c) trh nebo typ zákazníka (například státní a nestátní zákazníci); d) typ smlouvy (například smlouvy s pevně stanovenou cenou a smlouvy o dodávce materiálu a provedení práce); e) trvání smlouvy (například krátkodobé a dlouhodobé smlouvy); f) čas převodu zboží nebo služeb (například výnosy ze zboží nebo služeb převedené na zákazníka jednorázově a výnosy ze zboží nebo služeb převáděné průběžně) a g) prodejní kanály (například prodej zboží přímo spotřebitelům a prodej zboží přes prostředníky). Dodatek C Datum účinnosti a přechodná ustanovení Tento dodatek je nedílnou součástí tohoto standardu a má stejnou závaznost jako ostatní části tohoto standardu.'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 69, 'C2', 'a) se datem prvotní aplikace rozumí počátek vykazovaného období, ve kterém účetní jednotka poprvé uplatní tento standard, a b) dokončenou smlouvou se rozumí smlouva, u které účetní jednotka převedla veškeré zboží nebo služby identifikované v souladu s IAS 11 Smlouvy o zhotovení, IAS 18 Výnosy a s příslušnými interpretacemi.'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 70, 'C3', 'a) retrospektivně na každé předchozí vykazované období prezentované v souladu s IAS 8 Účetní pravidla, změny v účetních odhadech a chyby a s využitím zjednodušení uvedených v odstavci C5; b) retrospektivně s kumulativním dopadem prvotní aplikace tohoto standardu uznaným k datu prvotní aplikace v souladu s odstavci C7–C8.'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 71, 'C5', 'a) u dokončených smluv nemusí účetní jednotka měnit jejich vykazování, pokud: i) začínají i končí v témže ročním vykazovaném období nebo ii) jsou dokončené na počátku nejdřívějšího vykazovaného období; b) u dokončených smluv, které mají variabilní protihodnotu, může účetní jednotka použít transakční cenu k datu, kdy byla smlouva dokončena, a nikoli odhadovat částky variabilní protihodnoty ve srovnatelných vykazovaných obdobích; c) u smluv, které byly změněny před začátkem nejdřívějšího vykazovaného období, nemusí účetní jednotka změnit vykázání smlouvy v případě změny smlouvy v souladu s odstavci 20–21. Namísto toho musí účetní jednotka zohlednit celkový dopad všech změn, k nimž došlo před začátkem nejdřívějšího vykazovaného období, při: i) identifikaci závazků k plnění, které byly splněny, a závazků k plnění, které splněny nebyly; ii) určování transakční ceny a iii) přiřazování transakční ceny ke splněným a nesplněným závazkům k plnění; d) u všech vykazovaných období prezentovaných před datem prvotní aplikace nemusí účetní jednotka zveřejňovat částky transakční ceny přidělené na zbývající závazky k plnění ani vysvětlení toho, kdy očekává, že uzná tuto částku do výnosů (viz odstavec 120).'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 72, 'C6', 'a) zjednodušení, která byla využita, a b) v přiměřeně možném rozsahu kvalitativní posouzení odhadovaného dopadu použití těchto jednotlivých zjednodušení.'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 73, 'C7A', 'a) pro všechny změny smlouvy, k nimž dojde před začátkem vykazovaného období, nebo b) pro všechny změny smlouvy, k nimž dojde před začátkem prvotní aplikace. Pokud účetní jednotka využije toto praktické zjednodušení, musí je použít konzistentně u všech smluv a zveřejnit informace požadované dle odstavce C6.'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 74, 'C8', 'a) částky, jimiž jsou ovlivněny jednotlivé řádkové položky účetní závěrky v běžném vykazovaném období při aplikaci tohoto standardu v porovnání s IAS 11, IAS 18 a s příslušnými interpretacemi, které byly účinné před touto změnou, a b) vysvětlení důvodů podstatných změn uvedených v odst. C8 písm. a).'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 75, 'C8A', 'Odkazy na IFRS 9'),
('d2ad04d0-d40c-465f-b87b-38a584f7977f', 76, 'C10', 'a) IAS 11 Smlouvy o zhotovení; b) IAS 18 Výnosy; c) IFRIC 13 Zákaznické věrnostní programy; d) IFRIC 15 Smlouvy o zhotovení nemovitostí; e) IFRIC 18 Převody aktiv od zákazníků a f) SIC-31 Výnosy – barterové transakce zahrnující reklamní služby.')
